parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "proposed_outcome": {
      "type": "string",
      "enum": [
        "reconcile",
        "accept_variance",
        "escalate"
      ],
      "description": "What should happen to this invoice."
    },
    "exception_type": {
      "type": "string",
      "enum": [
        "none",
        "price_variance",
        "unagreed_charge",
        "quantity_short",
        "quantity_over",
        "wrong_po",
        "missing_bol",
        "unsigned_bol",
        "item_not_on_po",
        "duplicate_invoice",
        "suspicious_document",
        "other"
      ],
      "description": "Main exception found, or none."
    },
    "po_number": {
      "type": [
        "string",
        "null"
      ],
      "description": "PO the invoice matches, or null."
    },
    "bol_ids": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "BOLs used in the match."
    },
    "variance_amount": {
      "type": "number",
      "description": "Invoice total minus the PO-priced amount for the billed quantities. Positive means overbilled."
    },
    "exception_reason": {
      "type": "string",
      "description": "One plain sentence for the person who picks this up. Empty when there is no exception."
    },
    "confidence": {
      "type": "number",
      "description": "0 to 1. How sure you are that the recommendation is right given what the tools returned. Below 0.5 means you are guessing."
    },
    "rationale": {
      "type": "string",
      "description": "Two to five sentences a reviewer can check against the tool results. Cite the record ids you relied on."
    },
    "questions_for_human": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "If a person has to decide, the specific questions they need to answer. Empty when nothing is open."
    }
  },
  "required": [
    "proposed_outcome",
    "exception_type",
    "po_number",
    "bol_ids",
    "variance_amount",
    "exception_reason",
    "confidence",
    "rationale",
    "questions_for_human"
  ],
  "additionalProperties": false
}

parameters.jsCode:
// Deterministic checks. The agent's output is a proposal; nothing here trusts it
// without comparing against config or a fresh read of the system of record.
const cfg = $('Config').first().json;
const out = $('Document exception agent').item.json.output ?? null;
const reasons = [];
if (!out) reasons.push('agent_produced_no_valid_output');
if (out && !(typeof out.confidence === 'number' && out.confidence >= cfg.min_confidence)) {
  reasons.push('confidence ' + out?.confidence + ' below ' + cfg.min_confidence);
}

const req = $('Normalize document').item.json;
// Fresh read: { invoice: { status, vendor_id, po_number, currency, total, lines, duplicate_of }, po: { po_number, vendor_id, status, currency, lines } | null, bols: [{ bol_id, po_number, signed, lines }] }
const inv = $json.invoice ?? null;
const po = $json.po ?? null;
const bols = $json.bols ?? [];
const r2 = (n) => Math.round(n * 100) / 100;
const fmt = (n) => r2(n).toFixed(2);

if (!inv) reasons.push('invoice ' + req.document_id + ' not found');
if (out?.proposed_outcome === 'escalate') reasons.push('agent escalates: ' + (out.exception_reason || out.exception_type));
if (inv && !cfg.open_statuses.includes(inv.status)) reasons.push('invoice status is now ' + inv.status);
if (inv?.duplicate_of) reasons.push('invoice looks like a duplicate of ' + inv.duplicate_of);

// Wrong PO.
if (!po) reasons.push('wrong PO: no purchase order ' + (out?.po_number || req.po_number || '(none on invoice)') + ' found');
if (inv && po) {
  if (po.vendor_id !== inv.vendor_id) reasons.push('wrong PO: ' + po.po_number + ' belongs to vendor ' + po.vendor_id + ', the invoice is from ' + inv.vendor_id);
  if (inv.po_number && inv.po_number !== po.po_number) reasons.push('wrong PO: the invoice names ' + inv.po_number + ' but the match uses ' + po.po_number + '; a person must confirm');
  if (!inv.po_number) reasons.push('invoice names no PO; ' + po.po_number + ' was found by search and a person must confirm it');
  if (!['open', 'partially_received', 'received'].includes(po.status)) reasons.push('PO ' + po.po_number + ' is ' + po.status);
  if (po.currency && inv.currency && po.currency !== inv.currency) reasons.push('invoice currency ' + inv.currency + ' differs from PO currency ' + po.currency);
}

// Bills of lading.
if (po && !bols.length) reasons.push('missing BOL: no bill of lading found for PO ' + po.po_number);
for (const b of bols) {
  if (po && b.po_number !== po.po_number) reasons.push('BOL ' + b.bol_id + ' is for PO ' + b.po_number + ', not ' + po.po_number);
  if (b.signed !== true) reasons.push('BOL ' + b.bol_id + ' is not signed at delivery');
}
const bolQty = {};
for (const b of bols) for (const l of b.lines ?? []) bolQty[l.item] = (bolQty[l.item] ?? 0) + Number(l.qty);

// Recompute the match line by line.
let billed = 0;
let expected = 0;
const lines = inv?.lines ?? [];
if (inv && !lines.length) reasons.push('invoice has no lines to match');
for (const l of lines) {
  const qty = Number(l.qty);
  const price = Number(l.unit_price);
  billed += qty * price;
  const pl = (po?.lines ?? []).find((p) => p.item === l.item && (p.type ?? 'goods') === (l.type ?? 'goods'));
  if ((l.type ?? 'goods') === 'goods') {
    if (po && !pl) { reasons.push('item ' + l.item + ' is not on PO ' + po.po_number); continue; }
    const shipped = bolQty[l.item] ?? 0;
    if (bols.length && qty > shipped) reasons.push('quantity short: invoice bills ' + qty + ' of ' + l.item + ', BOL shows ' + shipped);
    if (pl && qty > Number(pl.qty)) reasons.push('quantity over: invoice bills ' + qty + ' of ' + l.item + ', PO ordered ' + pl.qty);
    if (pl) expected += qty * Number(pl.unit_price);
  } else if (pl) {
    // Agreed charge: priced as on the PO.
    expected += Number(pl.qty ?? 1) * Number(pl.unit_price);
  }
  // A charge not on the PO adds nothing to expected, so it shows up in the variance.
}
billed = r2(billed);
expected = r2(expected);
if (inv && Math.abs(billed - Number(inv.total)) > 0.01) reasons.push('invoice lines add up to ' + fmt(billed) + ' but the invoice total is ' + fmt(Number(inv.total)));
const variance = r2(Number(inv?.total ?? billed) - expected);
const pct = expected > 0 ? r2((variance / expected) * 100) : (variance === 0 ? 0 : Infinity);
const absV = Math.abs(variance);
const absP = Math.abs(pct);
if (out && Math.abs(Number(out.variance_amount) - variance) > 0.01) reasons.push('agent variance ' + out.variance_amount + ' differs from recomputed ' + fmt(variance));
if (absV > cfg.approval_limit_amount || absP > cfg.approval_limit_pct) reasons.push('variance ' + fmt(variance) + ' ' + (inv?.currency ?? '') + ' (' + pct + '%) is above the approval limit of ' + cfg.approval_limit_amount + ' or ' + cfg.approval_limit_pct + '%');

// The envelope: a clean three-way match with the variance inside both auto tolerances.
const withinEnvelope = absV <= cfg.tolerance_amount && absP <= cfg.tolerance_pct;
const action = {
  type: withinEnvelope ? 'reconcile' : 'accept_variance',
  document_id: req.document_id,
  invoice_number: inv?.invoice_number ?? req.invoice_number,
  po_number: po?.po_number ?? null,
  bol_ids: bols.map((b) => b.bol_id),
  billed_amount: billed,
  expected_amount: expected,
  variance_amount: variance,
  variance_pct: Number.isFinite(pct) ? pct : null,
};
const summary = 'Invoice ' + action.invoice_number + ' from ' + req.vendor_id + ' against PO ' + action.po_number + ' and BOL ' + action.bol_ids.join(', ') + ': billed ' + fmt(billed) + ', PO prices give ' + fmt(expected)
  + ', variance *' + fmt(variance) + ' ' + req.currency + ' (' + pct + '%)*, above the auto tolerance of ' + cfg.tolerance_amount + ' or ' + cfg.tolerance_pct + '%. Approve to accept the variance.\n'
  + (out?.exception_reason ? out.exception_reason + '\n' : '') + (out?.rationale ?? '');
const ok = reasons.length === 0;
const isNoop = typeof noop !== 'undefined' && noop === true;
const route = !ok ? 'escalate' : isNoop ? 'none' : withinEnvelope ? 'auto' : 'approve';
return { json: { business_key: req.business_key, route, within_envelope: withinEnvelope, guardrail_reasons: reasons, action, approval_summary: summary, planned_actions: ok && !isNoop ? [action] : [] } };

// The approval request goes to one named person, so the approver is that person.
// Slack returns { data: { approved, respondedAt } }; a timeout resumes without it.
const cfg = $('Config').first().json;
const approved = $json.data?.approved;
return {
  json: {
    decision: approved === true ? 'approved' : approved === false ? 'declined' : 'timed_out',
    approver: cfg.approver_slack_user,
    decided_at: $json.data?.respondedAt ?? new Date().toISOString(),
    handoff_reason: approved === true || approved === false ? '' : 'approval timed out after ' + cfg.approval_timeout_hours + ' hours',
  },
};

// Done only when the system of record shows what was planned.
const planned = $('Guardrails').item.json.action;
const m = $json.match ?? {};
const ok = $json.status === 'matched' && m.po_number === planned.po_number && Math.abs(Number(m.variance_amount) - Number(planned.variance_amount)) <= 0.01;
const detail = 'invoice shows status ' + $json.status + ' against PO ' + m.po_number + ' with variance ' + m.variance_amount + '; planned PO ' + planned.po_number + ' with variance ' + planned.variance_amount;
return { json: { verified: ok, verify_failed: !ok, verify_detail: ok ? '' : detail } };

// Collects everything a reviewer needs in one record: the request, what the agent
// proposed, why the guardrails stopped it, and the tool calls behind it.
const intake = $('Normalize document').item.json;
let agent = null;
let guard = null;
try { agent = $('Document exception agent').item.json; } catch (e) {}
try { guard = $('Guardrails').item.json; } catch (e) {}

const reasons = [...(guard?.guardrail_reasons ?? [])];
if ($json.error) reasons.push('system_error: ' + ($json.error.message ?? JSON.stringify($json.error)).slice(0, 300));
if ($json.verify_failed) reasons.push('verification_failed: ' + $json.verify_detail);
if ($json.handoff_reason) reasons.push($json.handoff_reason);
if (!agent?.output && !reasons.length) reasons.push('agent_produced_no_valid_output');
if (!reasons.length) {
  const o = agent.output;
  reasons.push('agent recommends review: ' + (o.decision ?? o.recommended_action ?? o.classification ?? o.route_to_queue ?? 'see proposal'));
}

const trace = (agent?.intermediateSteps ?? []).map((s) => ({
  tool: s.action?.tool,
  input: s.action?.toolInput,
  observation: String(s.observation ?? '').slice(0, 1500),
}));

return {
  json: {
    business_key: intake.business_key,
    team: "freight audit",
    reasons,
    proposed: agent?.output ?? null,
    confidence: agent?.output?.confidence ?? null,
    questions: agent?.output?.questions_for_human ?? [],
    trace,
    summary: 'Invoice ' + (intake.invoice_number || intake.document_id) + ' · vendor ' + intake.vendor_id + ' · PO ' + (intake.po_number || 'none') + ' · ' + (agent?.output?.exception_type ?? 'no result'),
  },
};

